shopify.query:
query AdsHeartbeatSep12EveningOrderCounts {
  shop { id name ianaTimezone }
  allNew: ordersCount(query:"created_at:>='2026-09-12T14:49:48Z' created_at:<'2026-09-12T18:51:58Z'",limit:null) { count precision }
  webNonTest: ordersCount(query:"created_at:>='2026-09-12T14:49:48Z' created_at:<'2026-09-12T18:51:58Z' source_name:web test:false",limit:null) { count precision }
  paidWebNonTest: ordersCount(query:"created_at:>='2026-09-12T14:49:48Z' created_at:<'2026-09-12T18:51:58Z' source_name:web test:false financial_status:paid",limit:null) { count precision }
}
